#include <stdlib.h>
#include <string.h>

char *duplicate(const char *s) {
    size_t n = strlen(s) + 1;   // +1 pro \0
    char *copy = malloc(n);
    if (!copy) return NULL;     // checar sempre
    memcpy(copy, s, n);
    return copy;                // caller vira dono
}

