// 2. Double free: free chamado 2x no mesmo pointer
free(p); free(p);     // corrompe allocator metadata

// 3. Use-after-free: usa depois de liberar
free(p);
printf("%s\n", p);    // ASan detecta

// 4. Buffer overflow: escreve além do tamanho
